        <?php foreach($agenda_days as $day=>$day_sessions): $first_start=(string)get_post_meta($day_sessions[0]->ID,'_cia_session_start',true); $day_date=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$first_start,cia_event_timezone()); $month_id=array(1=>'Jan',2=>'Feb',3=>'Mar',4=>'Apr',5=>'Mei',6=>'Jun',7=>'Jul',8=>'Agu',9=>'Sep',10=>'Okt',11=>'Nov',12=>'Des'); $date_label=$day_date ? ($lang==='en' ? $day_date->format('j M Y') : $day_date->format('j').' '.$month_id[(int)$day_date->format('n')].' '.$day_date->format('Y')) : ''; ?>
        <section class="event-agenda-day" aria-labelledby="event-agenda-day-<?php echo esc_attr((string)$day); ?>"><header><p><?php echo esc_html($copy['day'].' '.$day); ?></p><h3 id="event-agenda-day-<?php echo esc_attr((string)$day); ?>"><?php echo esc_html($date_label); ?></h3></header><ol>
          <?php foreach($day_sessions as $session): $session_start=(string)get_post_meta($session->ID,'_cia_session_start',true); $session_end=(string)get_post_meta($session->ID,'_cia_session_end',true); $room=(string)get_post_meta($session->ID,'_cia_session_room',true); $moderator=(string)get_post_meta($session->ID,'_cia_session_moderator',true); $session_type=(string)get_post_meta($session->ID,'_cia_session_type',true); $speaker_text=(string)get_post_meta($session->ID,'_cia_session_speakers_text',true); $session_speakers=array_values(array_filter(array_map('trim',preg_split('/\R/',$speaker_text)))); $plain=trim(wp_strip_all_tags(strip_shortcodes($session->post_content))); $session_title=get_the_title($session); if(str_starts_with($plain,$session_title)){$plain=trim(substr($plain,strlen($session_title)));} $description=trim((string)preg_split('/\s+Moderator:\s*/i',$plain,2)[0]); ?>
          <li id="session-<?php echo esc_attr((string)$session->ID); ?>" class="event-session-item" data-event-session="<?php echo esc_attr((string)$session->ID); ?>"><details><summary class="event-session-summary"><time datetime="<?php echo esc_attr(str_replace(' ','T',$session_start)); ?>"><strong><?php echo esc_html(substr($session_start,11,5)); ?></strong><span>–<?php echo esc_html(substr($session_end,11,5)); ?> WIB</span></time><span><small><?php echo esc_html($session_type); ?></small><strong><?php echo esc_html($session_title); ?></strong><?php if($room): ?><em><?php echo esc_html($room); ?></em><?php endif; ?></span><b aria-hidden="true">+</b></summary><div class="event-session-detail"><?php if($description): ?><p><?php echo esc_html(wp_trim_words($description,70)); ?></p><?php endif; ?><dl class="event-session-people"><?php if($moderator): ?><div><dt><?php echo esc_html($copy['moderator']); ?></dt><dd><?php echo esc_html($moderator); ?></dd></div><?php endif; ?><?php if($session_speakers): ?><div class="event-session-speakers"><dt><?php echo esc_html($copy['session_speakers']); ?></dt><dd><?php echo esc_html(implode(' · ',$session_speakers)); ?></dd></div><?php endif; ?><?php if($room): ?><div><dt><?php echo esc_html($copy['room']); ?></dt><dd><?php echo esc_html($room); ?></dd></div><?php endif; ?></dl></div></details></li>
          <?php endforeach; ?></ol></section><?php endforeach; ?>
