      <?php if($event_calls): ?><section id="event-opportunities" class="event-opportunities" aria-labelledby="event-opportunities-title"><header class="event-people-heading"><span class="media-kicker section-brow"><?php echo esc_html(sprintf('%02d',count($event_calls))); ?></span><div><h2 id="event-opportunities-title"><?php echo esc_html($copy['opportunities']); ?></h2><p><?php echo esc_html($copy['opportunities_intro']); ?></p></div></header><ol class="event-call-list">
        <?php foreach($event_calls as $call): $call_type=(string)get_post_meta($call->ID,'_cia_call_type',true); if(!in_array($call_type,array('proposal','sponsor','volunteer'),true)){$call_type='proposal';} $call_state=cia_event_call_state($call->ID); $call_title=cia_event_call_localized($call->ID,'title',$lang); $call_summary=cia_event_call_localized($call->ID,'summary',$lang); $call_close=(string)get_post_meta($call->ID,'_cia_call_close',true); $call_close_date=$call_close ? DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$call_close,cia_event_timezone()) : false; $call_url=cia_localized_url(get_permalink($call),$lang); ?>
        <li class="event-call-item"><div><p class="event-call-type"><?php echo esc_html($copy['call_'.$call_type]); ?></p><h3><a href="<?php echo esc_url($call_url); ?>"><?php echo esc_html($call_title); ?></a></h3><?php if($call_summary): ?><p><?php echo esc_html($call_summary); ?></p><?php endif; ?></div><div class="event-call-action"><span class="event-call-state event-call-state-<?php echo esc_attr($call_state); ?>"><?php echo esc_html($copy['call_'.$call_state]); ?></span><?php if($call_close_date): ?><small><?php echo esc_html($copy['call_deadline'].' '.$call_close_date->format('d M Y · H:i').' WIB'); ?></small><?php endif; ?><a class="event-call-link" href="<?php echo esc_url($call_url); ?>"><?php echo esc_html($copy['view_call']); ?> →</a></div></li>
        <?php endforeach; ?></ol></section><?php endif; ?>
      <?php if($speakers && !is_wp_error($speakers)): ?><section class="event-people event-speakers" aria-labelledby="event-speakers-title"><header class="event-people-heading"><span class="media-kicker section-brow"><?php echo esc_html(sprintf('%02d',count($speakers))); ?></span><h2 id="event-speakers-title"><?php echo esc_html($copy['speakers']); ?></h2></header><div class="event-speaker-grid"><?php foreach($speakers as $speaker):
        $person=cia_people_directory_record($speaker->term_id); $portrait='';
        $candidate=(string)($person['portrait']['theme_path'] ?? '');
