        $initials=cia_entity_initials($speaker->name);
      ?><article class="event-speaker-card"><a class="event-speaker-portrait" href="<?php echo esc_url($speaker_link); ?>"><?php if($portrait): ?><img src="<?php echo esc_url(get_template_directory_uri().'/'.$portrait); ?>" alt="" width="400" height="400" loading="lazy" decoding="async"><?php else: ?><span aria-hidden="true"><?php echo esc_html($initials); ?></span><span class="screen-reader-text"><?php echo esc_html($copy['speaker_fallback']); ?></span><?php endif; ?></a><div><p><?php echo esc_html($copy['speaker_role']); ?></p><h3><a href="<?php echo esc_url($speaker_link); ?>"><?php echo esc_html($speaker->name); ?></a></h3><?php if(!empty($person['affiliation_note'])): ?><small><?php echo esc_html($person['affiliation_note']); ?></small><?php endif; ?></div></article><?php endforeach; ?></div></section><?php endif; ?>
      <?php if($support): ?><section class="event-people event-collaborators" aria-labelledby="event-collaborators-title"><header class="event-people-heading"><span class="media-kicker section-brow"><?php echo esc_html(sprintf('%02d',count($support))); ?></span><div><h2 id="event-collaborators-title"><?php echo esc_html($copy['support']); ?></h2><p><?php echo esc_html($copy['support_intro']); ?></p></div></header><div class="event-collaborator-grid"><?php foreach($support as $entry): $item=$entry['term']; $display_name=$display_names[$item->slug] ?? $item->name; $logo=cia_partner_logo_record($item->slug); $logo_file=(string)($logo['file'] ?? ''); $event_url=add_query_arg('event_collaborator',$entry['taxonomy'].':'.$item->slug,cia_localized_url(get_post_type_archive_link('events'),$lang)); ?><a class="event-collaborator-card" href="<?php echo esc_url($event_url); ?>"><span class="event-collaborator-logo <?php echo in_array($item->slug,$dark_logos,true)?'is-dark':''; ?>"><?php if($logo_file): ?><img src="<?php echo esc_url(get_template_directory_uri().'/assets/partner-logos/'.$logo_file); ?>" alt="<?php echo esc_attr($display_name.' logo'); ?>" loading="lazy" decoding="async"><?php else: ?><span aria-hidden="true"><?php echo esc_html(cia_entity_initials($display_name)); ?></span><span class="screen-reader-text"><?php echo esc_html($copy['logo_fallback']); ?></span><?php endif; ?></span><span><small><?php echo esc_html($entry['role']); ?></small><strong><?php echo esc_html($display_name); ?></strong></span></a><?php endforeach; ?></div></section><?php endif; ?>
