        <div><dt><?php echo esc_html($copy['where']); ?></dt><dd><?php echo esc_html($venue ?: $copy['unverified']); ?><?php if($google_map_link): ?><a href="<?php echo esc_url($google_map_link); ?>" rel="external noopener"><?php echo esc_html($copy['map']); ?> ↗</a><?php endif; ?></dd></div>
        <div><dt><?php echo esc_html($copy['format']); ?></dt><dd><?php echo ($types && !is_wp_error($types)) ? esc_html(implode(', ',wp_list_pluck($types,'name'))) : esc_html($copy['unverified']); ?></dd></div>
      </dl>
      <?php if($state==='open' && $registration_link): ?><a class="event-register-button" href="<?php echo esc_url($registration_link); ?>" rel="external noopener"><?php echo esc_html($copy['register']); ?> ↗</a><?php else: ?><div class="event-registration-note"><?php echo esc_html($copy[$state]); ?></div><?php endif; ?>
      <?php if($public_webinar): ?><a class="event-stream-link" href="<?php echo esc_url($public_webinar); ?>" rel="external noopener"><?php echo esc_html($copy['stream']); ?> ↗</a><?php endif; ?>
    </div></aside>
  </div></section>
</article>
